-- 0078 (M7 hide demo clubs) — POSTCHECK. READ ONLY: one SELECT, changes nothing.
-- Run in the SQL editor (no signed-in user, so auth.uid() is null: the 'signed-out visitor' rows show exactly
-- what anon sees). Run after 0078 (switch not set: demo clubs still visible) and again after the switch is set
-- (visible = 0). Every row must be ok = true.
with checks(item, ok, detail) as (
  select 'clubs policies are the 0078 set', (select string_agg(policyname || ':' || cmd, ',' order by policyname) from pg_policies where tablename = 'clubs') = 'clubs: admin delete:DELETE,clubs: admin insert:INSERT,clubs: admin update:UPDATE,clubs: read:SELECT', coalesce((select string_agg(policyname || ':' || cmd, ',' order by policyname) from pg_policies where tablename = 'clubs'), 'none')
  union all select 'clubs read policy uses club_readable_by_me', (select qual from pg_policies where tablename = 'clubs' and policyname = 'clubs: read') = 'club_readable_by_me(id, is_demo)', coalesce((select qual from pg_policies where tablename = 'clubs' and policyname = 'clubs: read'), 'missing')
  union all select 'anon can run club_readable_by_me (needed by the read policy)', has_function_privilege('anon', 'club_readable_by_me(uuid,boolean)', 'execute'), ''
  union all select 'anon cannot run the other helpers', not has_function_privilege('anon', 'club_visible_to_me(uuid,boolean)', 'execute') and not has_function_privilege('anon', 'demo_clubs_hidden()', 'execute') and not has_function_privilege('anon', 'club_has_my_history(uuid)', 'execute'), ''
  union all select 'signed-in users cannot run the switch or history helpers directly', not has_function_privilege('authenticated', 'demo_clubs_hidden()', 'execute') and not has_function_privilege('authenticated', 'club_has_my_history(uuid)', 'execute'), ''
  union all select 'assert_valid_court_slot: the 0078 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'bfb88c633487ccd9e5524c7467160c72' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_court_slot'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_court_slot'), 'missing')
  union all select 'club_day_slots: the 0078 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'a0190b61fcb807e9af2509c0dc83344c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_day_slots'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_day_slots'), 'missing')
  union all select 'club_discovery: the 0078 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '0be1df8e1b0731d52fc478918caa35b0' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_discovery'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_discovery'), 'missing')
  union all select 'club_has_my_history: the 0078 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '1c4f9c98435edaced45841fff5611b73' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_has_my_history'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_has_my_history'), 'missing')
  union all select 'club_readable_by_me: the 0078 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '7f008ed2b613ec2f9146a28461ce6408' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_readable_by_me'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_readable_by_me'), 'missing')
  union all select 'club_visible_to_me: the 0078 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'e73692ed82cd41ecb32b1fe795d441cc' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_visible_to_me'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'club_visible_to_me'), 'missing')
  union all select 'coaches_directory: the 0078 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '1081929be297ffd520511fac583ffdf0' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'coaches_directory'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'coaches_directory'), 'missing')
  union all select 'demo_clubs_hidden: the 0078 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '7a9956e6fc40e1787cd74bd5ad5e1165' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'demo_clubs_hidden'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'demo_clubs_hidden'), 'missing')
  union all select 'open_matches: the 0078 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '486a03e21aafa33e4ce317f79c92a9d1' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'open_matches'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'open_matches'), 'missing')
  union all select 'switch: hide_demo_clubs is ' || case when demo_clubs_hidden() then 'ON' else 'off' end, true, coalesce((select value from app_settings where key = 'hide_demo_clubs'), 'not set')
  union all select 'signed-out visitor: demo clubs readable match the switch (0 when ON, all when off)',
    (select count(*) from clubs where is_demo and club_readable_by_me(id, is_demo)) = case when demo_clubs_hidden() then 0 else (select count(*) from clubs where is_demo) end,
    (select count(*) from clubs where is_demo and club_readable_by_me(id, is_demo))::text || ' of ' || (select count(*) from clubs where is_demo)::text
  union all select 'signed-out visitor: every non-demo club stays readable',
    (select count(*) from clubs where not is_demo and not club_readable_by_me(id, is_demo)) = 0, ''
  union all select 'signed-out visitor: discovery shows demo clubs only when off',
    (select count(*) from club_discovery() d join clubs c on c.slug = d.slug where c.is_demo) = case when demo_clubs_hidden() then 0 else (select count(*) from club_discovery() d join clubs c on c.slug = d.slug where c.is_demo) end
    and (not demo_clubs_hidden() or not exists (select 1 from club_discovery() d join clubs c on c.slug = d.slug where c.is_demo)), ''
)
select item, ok, detail from checks order by ok, item;
